ly before committing.","tree":{"sha":"8e9bce4e032b1360c20001d6942497a261e17a44","url":"https://api.github.com/repos/pryzmatical/linkpulse/git/trees/8e9bce4e032b1360c20001d6942497a261e17a44"},"url":"https://api.github.com/repos/pryzmatical/linkpulse/git/commits/a219b3cdb57d200509b65f58b2dd91abd8c352dd","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/311194351?v=4","events_url":"https://api.github.com/users/pryzmatical/events{/privacy}","followers_url":"https://api.github.com/users/pryzmatical/followers","following_url":"https://api.github.com/users/pryzmatical/following{/other_user}","gists_url":"https://api.github.com/users/pryzmatical/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/pryzmatical","id":311194351,"login":"pryzmatical","node_id":"U_kgDOEoxy7w","organizations_url":"https://api.github.com/users/pryzmatical/orgs","received_events_url":"https://api.github.com/users/pryzmatical/received_events","repos_url":"https://api.github.com/users/pryzmatical/repos","site_admin":false,"starred_url":"https://api.github.com/users/pryzmatical/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/pryzmatical/subscriptions","type":"User","url":"https://api.github.com/users/pryzmatical","user_view_type":"public"},"html_url":"https://github.com/pryzmatical/linkpulse/commit/a219b3cdb57d200509b65f58b2dd91abd8c352dd","node_id":"C_kwDOT0zW-NoAKGEyMTliM2NkYjU3ZDIwMDUwOWI2NWY1OGIyZGQ5MWFiZDhjMzUyZGQ","parents":[{"html_url":"https://github.com/pryzmatical/linkpulse/commit/ae2b9eac4f6bd1802a414b81e0937a6e499d5ede","sha":"ae2b9eac4f6bd1802a414b81e0937a6e499d5ede","url":"https://api.github.com/repos/pryzmatical/linkpulse/commits/ae2b9eac4f6bd1802a414b81e0937a6e499d5ede"}],"sha":"a219b3cdb57d200509b65f58b2dd91abd8c352dd","url":"https://api.github.com/repos/pryzmatical/linkpulse/commits/a219b3cdb57d200509b65f58b2dd91abd8c352dd"},