INSERT INTO collection_pages VALUES('b4b555f8c6ab4479153f9ea9c76ed7d6e3645438aaf2261589b5ef98f41b614b','fab82c9ce24e09db970023546f706c49a07e857e0867e8955867a550ffb2b495','{"hasNext":false,"items":[{"author":{"account":null,"email":"z@container","name":"Z User"},"authoredDate":"2026-08-11T15:51:41Z","committedDate":"2026-08-11T15:51:41Z","committer":{"account":null,"email":"z@container","name":"Z User"},"observedAt":"2026-10-09T00:09:09.306Z","repositoryId":1330712588,"sha":"0bd44e0315c3c7b5b38e22231937fb20a0647337"}],"observedAt":"2026-10-09T00:09:09.306Z","raw":[{"author":null,"comments_url":"https://api.github.com/repos/AFKmoney/neuro-paradigms-1b/commits/0bd44e0315c3c7b5b38e22231937fb20a0647337/comments","commit":{"author":{"date":"2026-08-11T15:51:41Z","email":"z@container","name":"Z User"},"comment_count":0,"committer":{"date":"2026-08-11T15:51:41Z","email":"z@container","name":"Z User"},"message":"Initial commit: 100 neuroscience-grounded paradigms, 1.6B tokens\n\n- 100 NEW disruptive software architecture paradigms, each grounded in\n  real published neuroscience research (Hebb, Hubel-Wiesel, Buzsaki,\n  Friston, Moser, etc.). No invented biology.\n- 300 JSONL chunk files (100 paradigms x 3 chunks each), gzip-compressed\n  (~200MB total, 37x compression).\n- 1,000,000 total entries across 8 entry types:\n  instruction_response (3.5k/paradigm), theory_math (1.4k),\n  code_multi_language (900), anti_patterns_failures (1.1k),\n  research_paper (1.5k), socratic_dialogue (800), benchmark_spec (500),\n  case_study (300).\n- ~1.61B estimated tokens.\n- Each entry varies across depth (introductory to open_problem),\n  audience (student to SRE), and perspective (theoretical to economic).\n- All content in English.\n- Generation scripts included for reproducibility.","tree":{"sha":"9780366d66b062d649aa4ea1c9281c14203ca684","url":"https://api.github.com/repos/AFKmoney/neuro-paradigms-1b/git/trees/9780366d66b062d649aa4ea1c9281c14203ca684"},"url":"https://api.github.com/r