INSERT INTO collection_pages VALUES('2a82a46d60ec830b6376172975ff3d22d9b217e5307345751e7cd68e4964a573','b8f057695c9a76b38221004b55534d4aece764b55c16463c1074c2b47a73e25e','{"hasNext":false,"items":[{"author":{"account":null,"email":"bot@care.local","name":"carefe-bot"},"authoredDate":"2026-08-11T20:40:07Z","committedDate":"2026-08-11T20:40:07Z","committer":{"account":null,"email":"bot@care.local","name":"carefe-bot"},"observedAt":"2026-10-09T00:09:57.895Z","repositoryId":1331323243,"sha":"2554ddce5466b848dd57210d9a9d6b3751ac2f52"},{"author":{"account":null,"email":"bot@care.local","name":"carefe-bot"},"authoredDate":"2026-08-11T20:35:36Z","committedDate":"2026-08-11T20:35:36Z","committer":{"account":null,"email":"bot@care.local","name":"carefe-bot"},"observedAt":"2026-10-09T00:09:57.895Z","repositoryId":1331323243,"sha":"b101210e3b09e26e57ad7b4dbf2e025956a14af9"},{"author":{"account":{"login":"amjithtitus09","providerType":"User"},"email":"amjithtitus09@gmail.com","name":"Amjith Titus"},"authoredDate":"2026-08-11T20:21:06Z","committedDate":"2026-08-11T20:21:06Z","committer":{"account":{"login":"amjithtitus09","providerType":"User"},"email":"amjithtitus09@gmail.com","name":"Amjith Titus"},"observedAt":"2026-10-09T00:09:57.895Z","repositoryId":1331323243,"sha":"6dbace69c54c27823bd2b96f20c7515cac03a1c5"}],"observedAt":"2026-10-09T00:09:57.895Z","raw":[{"author":null,"comments_url":"https://api.github.com/repos/ohcnetwork/care_people_fe/commits/2554ddce5466b848dd57210d9a9d6b3751ac2f52/comments","commit":{"author":{"date":"2026-08-11T20:40:07Z","email":"bot@care.local","name":"carefe-bot"},"comment_count":0,"committer":{"date":"2026-08-11T20:40:07Z","email":"bot@care.local","name":"carefe-bot"},"message":"docs: correct status block and document deployment\n\nThe README still described the plug as living inside care_fe/apps/ and\ntold the reader to extract it into its own repo, which is no longer true.\nReplace that with the build and Cloudflare Pages settings, and the\nREACT_ENABLED_APPS / plug_config values that point CARE at the deployed\nremoteEntry.js.\n\nCo-authored-by: Copilot App <223556219+Copilot@users.noreply.github.com>","tree":{"sha":"bc5243a9a2ba3b163abac5bdb0b1c4a69cfc40e9","url":"https://api.github.com/repos/ohcnetwork/care_people_fe/git/trees/bc5243a9a2ba3b163abac5bdb0b1c4a69cfc40e9"},"url":"https://api.github.com/repos/ohcnetwork/care_people_fe/git/commits/2554ddce5466b848dd57210d9a9d6b3751ac2f52","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/ohcnetwork/care_people_fe/commit/2554ddce5466b848dd57210d9a9d6b3751ac2f52","node_id":"C_kwDOT1pha9oAKDI1NTRkZGNlNTQ2NmI4NDhkZDU3MjEwZDlhOWQ2YjM3NTFhYzJmNTI","parents":[{"html_url":"https://github.com/ohcnetwork/care_people_fe/commit/b101210e3b09e26e57ad7b4dbf2e025956a14af9","sha":"b101210e3b09e26e57ad7b4dbf2e025956a14af9","url":"https://api.github.com/repos/ohcnetwork/care_people_fe/commits/b101210e3b09e26e57ad7b4dbf2e025956a14af9"}],"sha":"2554ddce5466b848dd57210d9a9d6b3751ac2f52","url":"https://api.github.com/repos/ohcnetwork/care_people_fe/commits/2554ddce5466b848dd57210d9a9d6b3751ac2f52"},{"author":null,"comments_url":"https://api.github.com/repos/ohcnetwork/care_people_fe/commits/b101210e3b09e26e57ad7b4dbf2e025956a14af9/comments","commit":{"author":{"date":"2026-08-11T20:35:36Z","email":"bot@care.local","name":"carefe-bot"},"comment_count":0,"committer":{"date":"2026-08-11T20:35:36Z","email":"bot@care.local","name":"carefe-bot"},"message":"fix: sync package-lock.json with package.json\n\n@radix-ui/react-checkbox and vaul were added to package.json for the tag\nfilter drawer/checkbox but never written to the lock file. `npm install`\nreconciles this silently, so it went unnoticed locally, but Cloudflare\nPages runs `npm clean-install`, which requires the two files to be in\nsync and fails with EUSAGE.\n\nVerified with `npm clean-install` followed by `npm run build`.\n\nCo-authored-by: Copilot App <223556219+Copilot@users.noreply.github.com>","tree":{"sha":"7745ced85af8f3a6976caaf641aa2bae89136ab2","url":"https://api.github.com/repos/ohcnetwork/care_people_fe/git/trees/7745ced85af8f3a6976caaf641aa2bae89136ab2"},"url":"https://api.github.com/repos/ohcnetwork/care_people_fe/git/commits/b101210e3b09e26e57ad7b4dbf2e025956a14af9","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/ohcnetwork/care_people_fe/commit/b101210e3b09e26e57ad7b4dbf2e025956a14af9","node_id":"C_kwDOT1pha9oAKGIxMDEyMTBlM2IwOWUyNmU1N2FkN2I0ZGJmMmUwMjU5NTZhMTRhZjk","parents":[{"html_url":"https://github.com/ohcnetwork/care_people_fe/commit/6dbace69c54c27823bd2b96f20c7515cac03a1c5","sha":"6dbace69c54c27823bd2b96f20c7515cac03a1c5","url":"https://api.github.com/repos/ohcnetwork/care_people_fe/commits/6dbace69c54c27823bd2b96f20c7515cac03a1c5"}],"sha":"b101210e3b09e26e57ad7b4dbf2e025956a14af9","url":"https://api.github.com/repos/ohcnetwork/care_people_fe/commits/b101210e3b09e26e57ad7b4dbf2e025956a14af9"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/37619282?v=4","events_url":"https://api.github.com/users/amjithtitus09/events{/privacy}","followers_url":"https://api.github.com/users/amjithtitus09/followers","following_url":"https://api.github.com/users/amjithtitus09/following{/other_user}","gists_url":"https://api.github.com/users/amjithtitus09/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/amjithtitus09","id":37619282,"login":"amjithtitus09","node_id":"MDQ6VXNlcjM3NjE5Mjgy","organizations_url":"https://api.github.com/users/amjithtitus09/orgs","received_events_url":"https://api.github.com/users/amjithtitus09/received_events","repos_url":"https://api.github.com/users/amjithtitus09/repos","site_admin":false,"starred_url":"https://api.github.com/users/amjithtitus09/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/amjithtitus09/subscriptions","type":"User","url":"https://api.github.com/users/amjithtitus09","user_view_type":"public"},"comments_url":"https://api.github.com/repos/ohcnetwork/care_people_fe/commits/6dbace69c54c27823bd2b96f20c7515cac03a1c5/comments","commit":{"author":{"date":"2026-08-11T20:21:06Z","email":"amjithtitus09@gmail.com","name":"Amjith Titus"},"comment_count":0,"committer":{"date":"2026-08-11T20:21:06Z","email":"amjithtitus09@gmail.com","name":"Amjith Titus"},"message":"feat: care_people_fe plug\n\nA CARE frontend plug that adds a facility-scoped People directory and the\nprimary_facility patient extension contract.\n\n- People page under the facility nav, backed by care_people_be''s\n  CarePeopleViewSet (/api/care_people_be/?facility=<uuid>)\n- Patient cards render instance and facility tags, linking through to the\n  patient within the facility\n- Tag filter chip rebuilt over MultiFilterStyleTagSelector, emitting\n  tags + tags_behavior to match core''s tag filtering contract\n- primary_facility patient extension documented in the README\n\nCo-authored-by: Copilot App <223556219+Copilot@users.noreply.github.com>","tree":{"sha":"7c27ad53248c03258a2453c1595e2e76e34e784e","url":"https://api.github.com/repos/ohcnetwork/care_people_fe/git/trees/7c27ad53248c03258a2453c1595e2e76e34e784e"},"url":"https://api.github.com/repos/ohcnetwork/care_people_fe/git/commits/6dbace69c54c27823bd2b96f20c7515cac03a1c5","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/37619282?v=4","events_url":"https://api.github.com/users/amjithtitus09/events{/privacy}","followers_url":"https://api.github.com/users/amjithtitus09/followers","following_url":"https://api.github.com/users/amjithtitus09/following{/other_user}","gists_url":"https://api.github.com/users/amjithtitus09/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/amjithtitus09","id":37619282,"login":"amjithtitus09","node_id":"MDQ6VXNlcjM3NjE5Mjgy","organizations_url":"https://api.github.com/users/amjithtitus09/orgs","received_events_url":"https://api.github.com/users/amjithtitus09/received_events","repos_url":"https://api.github.com/users/amjithtitus09/repos","site_admin":false,"starred_url":"https://api.github.com/users/amjithtitus09/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/amjithtitus09/subscriptions","type":"User","url":"https://api.github.com/users/amjithtitus09","user_view_type":"public"},"html_url":"https://github.com/ohcnetwork/care_people_fe/commit/6dbace69c54c27823bd2b96f20c7515cac03a1c5","node_id":"C_kwDOT1pha9oAKDZkYmFjZTY5YzU0YzI3ODIzYmQyYjk2ZjIwYzc1MTVjYWMwM2ExYzU","parents":[],"sha":"6dbace69c54c27823bd2b96f20c7515cac03a1c5","url":"https://api.github.com/repos/ohcnetwork/care_people_fe/commits/6dbace69c54c27823bd2b96f20c7515cac03a1c5"}],"requestUrl":"https://api.github.com/repos/ohcnetwork/care_people_fe/commits?per_page=100&page=1&sha=2554ddce5466b848dd57210d9a9d6b3751ac2f52&since=2025-03-31T23%3A59%3A59.000Z&until=2026-10-08T15%3A50%3A45.390Z"}');
